        "Công cụ nền, không phải tin ra mắt hôm nay",
        "[PhoBERT có bài nghiên cứu](https://aclanthology.org/2020.findings-emnlp.92/) trong Findings of EMNLP tháng 11/2020. [Tài liệu dự án](https://github.com/VinAIResearch/PhoBERT) yêu cầu đầu vào đã tách từ và khuyến nghị RDRSegmenter của VnCoreNLP. Bảng mô hình ghi giới hạn 256 token; bản base và large mang giấy phép MIT, còn base-v2 ghi AGPL v3. VnCoreNLP cung cấp các bước xử lý như tách từ, nhận diện thực thể và phân tích cú pháp; [giấy phép kho này](https://github.com/vncorenlp/VnCoreNLP/blob/master/LICENSE.md) là GPL v3 hoặc mới hơn. Những thông tin ấy mô tả thành phần kỹ thuật, không bảo đảm độ đúng của một bộ phân loại mới."
