      "evidence": "Nguồn [1] xác nhận nguồn gốc công trình, các bản mô hình và phương thức sử dụng. Nguồn [2] xác nhận giấy phép của bản small. Chưa có phép đo độc lập của bản tin; không dùng điểm trong kho để xếp hạng chất lượng cho mọi vùng giọng.",
      "method": "Chuẩn bị 36 đoạn giả lập đã có đồng ý ghi âm; tạo đáp án từ lời thực nói. Cố định tiền xử lý và quy tắc chấm. So sánh hai cấu hình theo thứ tự chạy hoán đổi, tách một nhóm nội dung mới để kiểm tra lại sau khi chỉnh thiết lập. Lưu bản chép thô và phiên bản đã sửa.",
      "measure": "Báo WER theo từng nhóm, lỗi thông tin trọng yếu, thời gian xử lý, phút sửa và lỗi còn sót. Báo cả đoạn im lặng và trường hợp thất bại. Chưa đủ dữ liệu thì công bố số đếm thay vì phần trăm dễ gây cảm giác chính xác giả.",
      "conditions": "Kết quả chỉ phản ánh người đọc, micro, môi trường và cấu hình đã thử. Giọng tự mô tả không đại diện vùng miền. Không dùng bản chép chưa kiểm để quyết định y tế, pháp lý hay tài chính; không đưa ghi âm người khác lên dịch vụ khi chưa có quyền.",
